import{_ as i,o as e,c as l,b3 as t}from"./chunks/framework.VnelH-cX.js";const f=JSON.parse('{"title":"WingShot 新功能","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features/wing-shot.md","filePath":"guide/features/wing-shot.md","lastUpdated":null}'),r={name:"guide/features/wing-shot.md"};function o(h,a,n,s,d,u){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="wingshot-新功能" tabindex="-1">WingShot 新功能 <a class="header-anchor" href="#wingshot-新功能" aria-label="Permalink to &quot;WingShot 新功能&quot;">​</a></h1><p>本页整理 Wing Shot 相较于 fork 基准版本新增或重点增强的能力。内容依据 Wing Shot 仓库提交记录汇总，具体表现以最新发布版本为准。</p><h2 id="快捷截图与文本处理" tabindex="-1">快捷截图与文本处理 <a class="header-anchor" href="#快捷截图与文本处理" aria-label="Permalink to &quot;快捷截图与文本处理&quot;">​</a></h2><ul><li>新增类似 PixPin 的 <code>Shift + C</code> 快速复制识别文本能力</li><li>新增截图后直接进入翻译页面的快捷流程</li><li>上次截图区域可独立保存，重复截取更方便</li><li>优化截图工具栏按钮顺序与高亮工具的默认体验</li></ul><div class="feature-image-placeholder">快捷截图与文本处理截图预留位置</div><h2 id="翻译能力增强" tabindex="-1">翻译能力增强 <a class="header-anchor" href="#翻译能力增强" aria-label="Permalink to &quot;翻译能力增强&quot;">​</a></h2><ul><li>翻译页面支持横向与纵向排版切换</li><li>支持手动选择翻译源，并可配置截图翻译使用手动或自动翻译源</li><li>支持语言对自动互转，减少重复切换源语言与目标语言</li><li>增加更多翻译平台接入方式与服务状态展示</li></ul><div class="feature-image-placeholder">翻译功能截图预留位置</div><h2 id="录屏与渲染" tabindex="-1">录屏与渲染 <a class="header-anchor" href="#录屏与渲染" aria-label="Permalink to &quot;录屏与渲染&quot;">​</a></h2><ul><li>录屏支持系统音频录制</li><li>新增 WebGPU 渲染引擎选项</li><li>增加截图日志与日志保留时长设置，便于定位问题</li></ul><div class="feature-image-placeholder">录屏与渲染设置截图预留位置</div><h2 id="贴图、滚动截图与图片工具" tabindex="-1">贴图、滚动截图与图片工具 <a class="header-anchor" href="#贴图、滚动截图与图片工具" aria-label="Permalink to &quot;贴图、滚动截图与图片工具&quot;">​</a></h2><ul><li>新增图片拼图工具</li><li>截图历史支持一键贴图</li><li>托盘可快速显示或隐藏贴图，并可恢复默认窗口位置与大小</li><li>贴图显示时可选择恢复默认大小，贴图编辑体验持续优化</li><li>滚动截图增加单击自动滚动开关</li></ul><div class="feature-image-placeholder">贴图与图片拼图截图预留位置</div><h2 id="ai-与插件服务" tabindex="-1">AI 与插件服务 <a class="header-anchor" href="#ai-与插件服务" aria-label="Permalink to &quot;AI 与插件服务&quot;">​</a></h2><ul><li>增强 AI 模型配置和模型供应商管理</li><li>完善 OCR 视觉模型接入</li><li>增加插件下载源降级配置，提升资源下载可用性</li></ul><p>更多变更可查看 <a href="https://github.com/Anfioo/WingShot/commits/" target="_blank" rel="noreferrer">Wing Shot 提交记录</a> 与 <a href="https://github.com/Anfioo/WingShot/releases" target="_blank" rel="noreferrer">版本发布页</a>。</p>',17)])])}const g=i(r,[["render",o]]);export{f as __pageData,g as default};
